// Read-only UI prototype. Resource configuration is illustrative; scan fixture is historical.
const prototypeControls = [
  { id:'PY-LIC-001', group:'Open Source & Lizenzen', name:'Zulässige Paketlizenzen', requirement:'Die Lizenz jedes Pakets muss in der freigegebenen Allowlist stehen.', example:false },
  { id:'SEC-API-001', group:'Anwendungssicherheit', name:'Öffentliche APIs verlangen eine Authentifizierung', requirement:'Zugriffe auf öffentliche APIs erfordern die festgelegte Authentifizierung.', example:true },
  { id:'PRIV-001', group:'Datenschutz', name:'Personenbezogene Daten sind verschlüsselt', requirement:'Für personenbezogene Daten muss die vorgesehene Verschlüsselung belegt sein.', example:true },
  { id:'OPS-001', group:'Betrieb & Resilienz', name:'Backups werden regelmäßig geprüft', requirement:'Ein Wiederherstellungstest muss für den vorgesehenen Zeitraum belegt sein.', example:true }
];
const params = new URLSearchParams(location.search);
const productViews=['Anforderungen','Geltungsbereich','Prüfungen'];
const resourceViews=['Produkte','Kataloge','Profile','Evidence Packs','Manifest','Registrieren'];
const state={view:params.get('view')||'Produkte',product:params.get('product')||'Audio Visualizer',scan:params.get('scan')||'license',filter:'all',packageFilter:'all',open:new Set(params.get('control')?[params.get('control')]:[])};
if(![...resourceViews,...productViews].includes(state.view))state.view='Produkte';
if(!['Audio Visualizer','Plattform API (Beispiel)'].includes(state.product))state.product='Audio Visualizer';
if(!['license','none'].includes(state.scan))state.scan='license';
if(resourceTypes[params.get('kind')])registryKind=params.get('kind');
let snapshot=null;
const esc=escapeConfig;
const sourceLink=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
const pill=(status,label)=>`<span class="pill ${status==='PASS'?'ok':status==='FAIL'?'':'unknown'}">${esc(label||({PASS:'Erfüllt',FAIL:'Nicht erfüllt',UNKNOWN:'Unklar',UNASSESSED:'Nicht bewertet'}[status]))}</span>`;
const profileLink=()=>`<button class="link" data-manifest="ControlProfile">Application Baseline · 1.0.0 →</button>`;
function announce(text){document.getElementById('live-status').textContent=text;}
function navigate(view,{control='',scan=null}={}){state.view=view;state.filter='all';state.packageFilter='all';if(control)state.open.add(control);if(scan)state.scan=scan;render();document.getElementById('page-title')?.focus();window.scrollTo(0,0);}
function scanned(){return state.product==='Audio Visualizer'&&state.scan==='license'&&snapshot;}
function controlStatus(c){return c.id==='PY-LIC-001'&&scanned()?'FAIL':'UNASSESSED';}
function emptyProduct(){return `<h1 id="page-title" tabindex="-1">${state.view==='Anforderungen'?'Controls für dieses Produkt':esc(state.view)}</h1><div class="card"><h2>Noch keine Beispieldaten</h2><p>Für dieses illustrative Produkt sind keine Controls oder Prüfungen hinterlegt.</p></div>`;}
function profileContext(){return `<div class="card profile-context"><div class="row spread"><div><span class="eyebrow">Aktuell zugeordnetes Profil · Entwurf</span><h2>${profileLink()}</h2><p class="muted">4 ausgewählte Controls aus Application Controls · 1.0.0. Quellenrevisionen noch nicht aufgelöst.</p></div><button class="link" data-page="Geltungsbereich">Zuordnung und Änderungsweg →</button></div></div>`;}
function sourceOfAssessment(){if(!snapshot)return '<p>Historischer Nachweisstand konnte nicht geladen werden.</p>';const a=snapshot.assessment;return `<details class="trace" data-open-key="assessment"><summary>Bewertungsstand und Herkunft anzeigen</summary><dl class="provenance"><dt>Prüfung / Assessment</dt><dd>${esc(a.id)}</dd><dt>Kontext</dt><dd>Repository · keine Produktionsprüfung</dd><dt>Beobachtungszeitpunkt</dt><dd>${esc(a.createdAt)}</dd><dt>Produktquelle</dt><dd>${sourceLink('https://github.com/djfun/audio-visualizer-python/commit/'+a.gitSha,a.gitSha)}</dd><dt>Geprüfte Datei</dt><dd>${sourceLink('https://github.com/djfun/audio-visualizer-python/blob/'+a.gitSha+'/uv.lock','uv.lock auf der geprüften Revision')}</dd><dt>Verwendete Regelquelle</dt><dd>${sourceLink('https://github.com/arturmiller/specbound/commit/'+a.packSha,a.packSha)}</dd><dt>Profil / Katalog des Scans</dt><dd>Im historischen Scan nicht gespeichert. Das aktuelle Entwurfsprofil oben ist keine rückwirkend belegte Quelle dieses Ergebnisses.</dd><dt>Nachweiserzeuger</dt><dd>Öffentlicher Python-Lizenzscanner · producerKind public-license-scan. Kein Collector-Image oder Evidence Pack verwendet.</dd><dt>Version des Erzeugers</dt><dd>Im gespeicherten Datensatz nicht ausgewiesen.</dd></dl><p class="muted">Die gespeicherten Nachweise sind historische Beobachtungen. Ihr Ablaufdatum bestimmt nicht, ob ein damaliges Ergebnis nachträglich geändert wird.</p></details>`;}
function packageEvidence(pkg){
  const evaluation=snapshot.evaluations.find(e=>e.name===pkg.name&&e.version===pkg.version&&e.path===pkg.path);
  const evidence=snapshot.evidence.filter(e=>evaluation?.evidenceIds.includes(e.id));
  return `<details class="package-evidence" data-open-key="pkg:${esc(pkg.name)}:${esc(pkg.version)}"><summary><span><b>${esc(pkg.name)} · ${esc(pkg.version)}</b><small>${esc(pkg.licenseExpression||'Keine eindeutige Lizenzdeklaration')}</small></span>${pill(pkg.status,pkg.status==='FAIL'?'Nicht freigegeben':undefined)}</summary><p>${esc(evaluation?.reason||pkg.metadata?.reason||'Keine belastbare Bewertung vorhanden.')}</p><p class="muted">Quelle: ${esc(pkg.path)} · ${esc(pkg.source)}</p>${evidence.length?evidence.map(e=>`<div class="evidence-record"><h3>Gespeicherter Nachweis</h3><dl class="provenance"><dt>Evidence-ID</dt><dd>${esc(e.id)}</dd><dt>Beobachtet</dt><dd>${esc(e.observedAt)}</dd><dt>Gültig bis</dt><dd>${esc(e.expiresAt)} · historischer Stand</dd><dt>Nachweisart</dt><dd>${esc(e.capability)}</dd><dt>Erzeuger</dt><dd>${esc(e.producerKind)}</dd></dl><h3>Tatsächlich verwendeter Inhalt</h3><pre tabindex="0" aria-label="Gespeicherter Evidenzinhalt">${esc(JSON.stringify(e.value,null,2))}</pre>${(e.value.artifacts||[]).map((artifact,i)=>`<details class="trace" data-open-key="artifact:${esc(e.id)}:${i}"><summary>Artefakt ${i+1}: Quelle und Integrität</summary><p>${sourceLink(artifact.sourceUrl,artifact.sourceKind)}</p><dl class="provenance"><dt>Artefakt SHA-256</dt><dd>${esc(artifact.artifactSha256)}</dd><dt>Metadaten SHA-256</dt><dd>${esc(artifact.metadataSha256)}</dd></dl></details>`).join('')}</div>`).join(''):`<p class="muted">Kein verifizierter Nachweis gespeichert: ${esc(pkg.metadata?.reason||'Metadaten nicht eindeutig belegt')}. Für UNKNOWN fehlt eine belastbare Bewertung.</p>`}</details>`;
}
function packageList(){return `<div class="package-panel"><div class="row spread"><div><h3>Alle ${snapshot.packages.length} Paketbewertungen</h3><p>2 nicht freigegeben · 3 erfüllt · 9 unklar. Diese Zahlen zählen Pakete, nicht Controls.</p></div><label>Paketstatus<select id="package-filter"><option value="all">Alle Pakete</option><option value="FAIL">Nicht freigegeben</option><option value="PASS">Erfüllt</option><option value="UNKNOWN">Unklar</option></select></label></div>${snapshot.packages.map(pkg=>`<div data-package-status="${esc(pkg.status)}">${packageEvidence(pkg)}</div>`).join('')}<p id="package-count" class="muted">${snapshot.packages.length} von ${snapshot.packages.length} Paketen sichtbar</p></div>`;}
function controlMarkup(c){const status=controlStatus(c);return `<section data-control-group="${c.id}"><h2>${c.group}</h2><details class="card control-card" data-control="${c.id}" data-status="${status}" data-open-key="${c.id}" ${state.open.has(c.id)?'open':''}><summary><span><b>${c.id} · ${c.name}</b>${c.example?'<small>Illustratives Control im Entwurfsprofil</small>':''}</span>${pill(status)}</summary><p>${c.requirement}</p>${status==='FAIL'?`<p>Die Allowlist erlaubt MIT, Apache-2.0, BSD-2-Clause, BSD-3-Clause und ISC. GPL-3.0-only und PSF-2.0 liegen außerhalb dieser Beispielrichtlinie.</p>${sourceOfAssessment()}${packageList()}`:`<p class="muted">${state.scan==='none'?'Keine Prüfung ausgewählt.':'Die ausgewählte Prüfung bewertet dieses Control nicht.'} Kein Bewertungsergebnis und keine zugehörigen Nachweise.</p>`}</details></section>`;}
function controlsPage(){return `<h1 id="page-title" tabindex="-1">Controls für dieses Produkt</h1><p class="lead">Anforderungen, vollständige Bewertungen und Nachweise am Control.</p>${profileContext()}<div class="card"><div class="row spread"><label>Prüfung auswählen<select id="scan-select"><option value="license" ${state.scan==='license'?'selected':''}>Lizenzscan · 13.11.2026 · 691c95e</option><option value="none" ${state.scan==='none'?'selected':''}>Keine Prüfung ausgewählt</option></select></label><label>Control-Status<select id="control-filter"><option value="all">Alle</option><option value="FAIL">Nicht erfüllt</option><option value="PASS">Erfüllt</option><option value="UNKNOWN">Unklar</option><option value="UNASSESSED">Nicht bewertet</option></select></label></div><p class="muted">${scanned()?'1 Control nicht erfüllt · 3 nicht bewertet':'4 Controls nicht bewertet'} · Die Zählung bezieht sich auf Controls, nicht auf Pakete.</p></div><div id="control-list">${prototypeControls.map(controlMarkup).join('')}</div><div class="card empty" id="control-empty" hidden><p>Keine Controls mit diesem Status in der ausgewählten Prüfung.</p><button class="btn secondary" id="reset-filter">Alle Controls anzeigen</button></div>${!snapshot?'<p role="alert">Der historische Datensatz konnte nicht geladen werden. Es werden keine Bewertungen behauptet.</p>':''}`;}
function scopePage(){return `<h1 id="page-title" tabindex="-1">Geltende Controls</h1><p class="lead">Das Produkt erhält seine Controls durch eine ausdrückliche Profilzuordnung.</p>${profileContext()}<div class="card"><h2>Herkunft der Zuordnung</h2><div class="flow"><div><b>Produkt</b><p>Audio Visualizer</p><button class="link" data-manifest="Product">Produktmanifest →</button></div><div><b>Profil</b><p>Application Baseline · 1.0.0</p><button class="link" data-manifest="ControlProfile">Profil öffnen →</button></div><div><b>Katalog</b><p>Application Controls · 1.0.0</p><button class="link" data-manifest="ControlCatalog">Katalog öffnen →</button></div></div><p class="muted">Beispielzuordnung: Profil- und Katalogquellen sind nicht auf einen Commit aufgelöst.</p><h2>Ausdrücklich ausgewählte Controls</h2>${prototypeControls.map(c=>`<p><b>${c.id}</b> · ${c.name}</p>`).join('')}<h2>Wie ändere ich die geltenden Anforderungen?</h2><p>Ein anderes Profil wird im Produktmanifest ausgewählt. Die gemeinsame Control-Auswahl wird im Profilmanifest geändert und betrifft Produkte, die diese Profilversion verwenden.</p><p>Für das Produkt gelten keine stillschweigenden Einzelabweichungen. Änderungen werden über das Repository versioniert; dieser Entwurf speichert sie nicht.</p><button class="link" data-manifest="Product">Konfiguration und Repository-Pfad ansehen →</button></div>`;}
function checksPage(){return `<h1 id="page-title" tabindex="-1">Prüfungen</h1><p class="lead">Historische Prüfungen mit festem Quellstand und vollständigen Bewertungen.</p><div class="card"><div class="row spread"><div><h2>Python-Lizenzen · abgeschlossen</h2><p>13.11.2026 · djfun/audio-visualizer-python · Commit 691c95e</p></div><button class="btn" data-open-scan>Bewertungen am Control öffnen →</button></div><p><b>14 Pakete:</b> 2 nicht freigegeben · 3 erfüllt · 9 unklar</p><p><b>Control:</b> PY-LIC-001 · nicht erfüllt</p>${sourceOfAssessment()}</div><div class="card" style="margin-top:20px"><h2>Neue Prüfung vorbereiten</h2><p>Vor einer tatsächlichen Ausführung müssen Quelle, Erhebungsumfang und Zugriffe geprüft werden.</p><details><summary>Vorgesehenen Umfang ansehen · Entwurf</summary><p>Öffentliche Lockfiles und PyPI-Artefaktmetadaten lesen; keinen Repository-Code ausführen. Für weitere Evidence Packs sind Berechtigungen und Datenumfang gesondert festzulegen.</p><p class="muted">Registrierung und Schema-Prüfung erteilen keine Ausführungsfreigabe.</p></details></div>`;}
function productScreen(){if(state.product!=='Audio Visualizer')return emptyProduct();return state.view==='Anforderungen'?controlsPage():state.view==='Geltungsbereich'?scopePage():checksPage();}
function render({restoreFocus=false}={}){
  const focusId=restoreFocus?document.activeElement?.id:null;
  const result=resourceViews.includes(state.view)?registryScreen(state.view):productScreen();
  document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar" aria-label="Hauptnavigation"><div class="brand"><b>◇</b> Specbound</div><nav aria-label="Ressourcen"><small>Ressourcen</small><div class="nav-items">${Object.entries(resourceTypes).map(([k,t])=>`<button data-resource="${k}" ${state.view===t.label?'aria-current="page"':''}>${t.label}</button>`).join('')}</div></nav><nav aria-label="Ausgewähltes Produkt"><small>Produkt</small><div class="nav-items">${productViews.map(v=>`<button data-page="${v}" ${state.view===v?'aria-current="page"':''}>${v}</button>`).join('')}</div></nav></aside><main class="main"><header class="top"><div class="row">${productViews.includes(state.view)?`<label>Produkt<select id="product-select"><option ${state.product==='Audio Visualizer'?'selected':''}>Audio Visualizer</option><option ${state.product==='Plattform API (Beispiel)'?'selected':''}>Plattform API (Beispiel)</option></select></label>`:''}<span>${esc(state.view)}</span></div><span>◉ Lokaler Entwurf</span></header><div class="content">${result}<p id="demo-message" role="status"></p></div></main></div>`;
  const h1=document.querySelector('h1');if(h1){h1.id='page-title';h1.tabIndex=-1;}
  mountRegistry(navigate,()=>{state.product='Audio Visualizer';navigate('Anforderungen');});
  document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));
  document.querySelector('[data-open-scan]')?.addEventListener('click',()=>navigate('Anforderungen',{control:'PY-LIC-001',scan:'license'}));
  document.getElementById('product-select')?.addEventListener('change',e=>{state.product=e.target.value;state.open.clear();state.scan='license';state.filter='all';state.packageFilter='all';render({restoreFocus:true});announce('Produkt geändert: '+state.product);});
  document.getElementById('scan-select')?.addEventListener('change',e=>{state.scan=e.target.value;state.filter='all';state.packageFilter='all';render({restoreFocus:true});announce(state.scan==='none'?'Keine Prüfung ausgewählt. Alle vier Controls sind nicht bewertet.':'Historischer Lizenzscan ausgewählt. Ein Control ist nicht erfüllt, drei sind nicht bewertet.');});
  document.querySelectorAll('[data-open-key]').forEach(d=>{d.open=state.open.has(d.dataset.openKey);d.addEventListener('toggle',()=>{if(d.open)state.open.add(d.dataset.openKey);else state.open.delete(d.dataset.openKey);});});
  document.getElementById('control-filter')?.addEventListener('change',e=>{state.filter=e.target.value;applyFilter();});
  document.getElementById('package-filter')?.addEventListener('change',e=>{state.packageFilter=e.target.value;applyPackageFilter();});
  document.getElementById('reset-filter')?.addEventListener('click',()=>{state.filter='all';applyFilter();document.getElementById('control-filter').focus();});
  applyFilter(false);applyPackageFilter();
  if(focusId)document.getElementById(focusId)?.focus();
  const url=new URL(location.href);url.search='';url.searchParams.set('view',state.view);if(productViews.includes(state.view)){url.searchParams.set('product',state.product);url.searchParams.set('scan',state.scan);}if(state.view==='Manifest'||state.view==='Registrieren')url.searchParams.set('kind',registryKind);history.replaceState(null,'',url);
}
function applyFilter(notify=true){const filter=document.getElementById('control-filter');if(!filter)return;filter.value=state.filter;let count=0;document.querySelectorAll('[data-control-group]').forEach(group=>{const d=group.querySelector('[data-status]');const show=state.filter==='all'||d.dataset.status===state.filter;group.hidden=!show;if(show)count++;});document.getElementById('control-empty').hidden=count>0;if(notify)announce(`${count} Controls sichtbar.`);}
function applyPackageFilter(){const filter=document.getElementById('package-filter');if(!filter)return;filter.value=state.packageFilter;let count=0;document.querySelectorAll('[data-package-status]').forEach(row=>{row.hidden=state.packageFilter!=='all'&&row.dataset.packageStatus!==state.packageFilter;if(!row.hidden)count++;});document.getElementById('package-count').textContent=`${count} von ${snapshot.packages.length} Paketen sichtbar`;}
async function boot(){try{const response=await fetch('/prototype-license-snapshot.json');if(response.ok)snapshot=await response.json();}catch{}render();}
boot();
